<template><AccountLayout bare><main class="am-page"><header><h1>Messages</h1><b>Account Number: AC-{{ String(authState.user?.id||0).padStart(6,'0') }}</b></header><div class="am-shell"><aside><button class="new" @click="view='compose';selected=null">＋ New Message</button><button :class="{active:view==='inbox'}" @click="open('inbox')">▱ Inbox <i>{{counts.inbox}}</i></button><button :class="{active:view==='sent'}" @click="open('sent')">➤ Sent <i>{{counts.sent}}</i></button><button :class="{active:view==='trash'}" @click="open('trash')">♜ Trash <i>{{counts.trash}}</i></button></aside><section class="am-content"><template v-if="view==='compose'"><h2>New Message</h2><div class="message-info"><span>Message No.<b>New outgoing message</b></span><span>Account No.<b>AC-{{String(authState.user?.id||0).padStart(6,'0')}}</b></span><span>Direction<b>OUT</b></span><span>Date<b>{{date(new Date())}}</b></span></div><form @submit.prevent="send"><label>From<input :value="authState.user?.company_name||authState.user?.name" disabled></label><label>To<select v-model="form.to_name"><option>Developer Support</option><option>Billing Support</option><option>Technical Support</option><option>Account Support</option></select></label><label>Subject<input v-model="form.subject" required placeholder="Enter message subject"></label><label>Message<textarea v-model="form.message" required placeholder="Write your message here..."></textarea></label><label class="attachment">📎 Attach File <small>PDF, DOCX, XLSX, JPG or PNG</small><input type="file" multiple accept=".pdf,.doc,.docx,.xls,.xlsx,.jpg,.jpeg,.png" @change="files=$event.target.files"></label><footer><button type="button" class="outline" @click="reset">Cancel</button><button class="primary">Send Message</button></footer></form></template><template v-else-if="selected"><button class="outline back" @click="selected=null">← Back to {{view==='sent'?'Sent':'Inbox'}}</button><h2>Read Message</h2><div class="read-meta"><b>Message No.</b><span>{{selected.message_no}}</span><b>Date</b><span>{{date(selected.sent_at)}}</span><b>Status</b><span>{{selected.status}}</span><b>From</b><span>{{selected.from_name}}</span><b>To</b><span>{{selected.to_name}}</span><b>Subject</b><span>{{selected.subject}}</span></div><article>{{selected.message}}</article><footer><button class="outline" @click="view='compose';form.to_name=selected.from_name;form.subject='Re: '+selected.subject;selected=null">Reply</button><button class="outline" @click="trash(selected)">Move to Trash</button><button class="primary" @click="selected=null">Back to {{view==='sent'?'Sent':'Inbox'}}</button></footer></template><template v-else><h2>{{title}}</h2><div class="toolbar"><input v-model="search" :placeholder="`Search ${title.toLowerCase()}`"><button v-if="view==='trash'" class="outline" @click="emptyTrash">Empty Trash</button></div><div class="table-wrap"><table><thead><tr><th>No.</th><th>Date</th><th>Time</th><th>{{view==='inbox'?'Message No.':view==='sent'?'Sent To':'From / To'}}</th><th>Subject</th><th>{{view==='trash'?'Original Folder':'Status'}}</th><th>Action</th></tr></thead><tbody><tr v-for="(m,i) in filtered" :key="m.id"><td>{{i+1}}</td><td>{{date(m.sent_at||m.deleted_at)}}</td><td>{{time(m.sent_at||m.deleted_at)}}</td><td>{{view==='inbox'?m.message_no:view==='sent'?m.to_name:(m.direction==='in'?'From: ':'To: ')+(m.direction==='in'?m.from_name:m.to_name)}}</td><td>{{m.subject}}</td><td>{{view==='trash'?m.deleted_from:m.status}}</td><td><button v-if="view!=='trash'" class="outline" @click="read(m)">{{view==='inbox'?'Read Details':'View Details'}}</button><template v-else><button class="outline" @click="restore(m)">Restore</button><button class="outline danger" @click="remove(m)">Delete Permanently</button></template></td></tr><tr v-if="!filtered.length"><td colspan="7">No messages found.</td></tr></tbody></table></div><small>Showing {{filtered.length}} of {{items.length}} {{title.toLowerCase()}} messages</small></template></section></div></main></AccountLayout></template>
<script setup>import{computed,ref,onMounted}from'vue';import AccountLayout from'../components/AccountLayout.vue';import client from'../api/client';import{authState}from'../store/auth';const view=ref('inbox'),items=ref([]),counts=ref({inbox:0,sent:0,trash:0}),selected=ref(null),search=ref(''),files=ref([]),form=ref({to_name:'Developer Support',subject:'',message:''});const title=computed(()=>view.value[0].toUpperCase()+view.value.slice(1));const filtered=computed(()=>items.value.filter(x=>`${x.subject} ${x.from_name} ${x.to_name}`.toLowerCase().includes(search.value.toLowerCase())));const date=x=>x?new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:'numeric'}).format(new Date(x)):'--';const time=x=>x?new Intl.DateTimeFormat('en-US',{hour:'numeric',minute:'2-digit'}).format(new Date(x)):'--';const load=async()=>{const{data}=await client.get('/account/messages',{params:{folder:view.value}});items.value=data.data;counts.value=data.counts};const open=x=>{view.value=x;selected.value=null;load()};const read=async m=>{const{data}=await client.get('/account/messages/'+m.id);selected.value=data.data;counts.value=data.counts};const send=async()=>{const d=new FormData;Object.entries(form.value).forEach(([k,v])=>d.append(k,v));[...files.value].forEach(f=>d.append('attachments[]',f));await client.post('/account/messages',d);reset();open('sent')};const reset=()=>{form.value={to_name:'Developer Support',subject:'',message:''};files.value=[]};const trash=async m=>{await client.post('/account/messages/'+m.id+'/trash');open(view.value==='sent'?'sent':'inbox')};const restore=async m=>{await client.post('/account/messages/'+m.id+'/restore');load()};const remove=async m=>{if(confirm('Delete this message permanently?')){await client.delete('/account/messages/'+m.id);load()}};const emptyTrash=async()=>{for(const m of items.value)await client.delete('/account/messages/'+m.id);load()};onMounted(load)</script>
<style scoped>.am-page{max-width:1260px;margin:0 auto;padding:10px 14px;color:#061a8f}.am-page header{display:flex;gap:24px;align-items:center}.am-page h1{flex:1;margin:0;padding:3px 16px;color:#fff;background:linear-gradient(100deg,#063c7c,#012263);border-radius:7px;font-size:2.3rem}.am-shell{display:grid;grid-template-columns:190px 1fr;gap:10px;margin-top:10px}.am-shell aside,.am-content{border:1px solid #c8d5e8;border-radius:7px;background:#fff;padding:7px}.am-shell aside button{display:flex;justify-content:space-between;align-items:center;width:100%;margin:5px 0;padding:10px;border:0;background:#fff;color:#0623a5;font-size:1.05rem;text-align:left}.am-shell aside .new,.primary{background:#0755ed!important;color:#fff!important;border-radius:5px}.am-shell aside .active{background:#eaf1ff}.am-shell i{padding:2px 7px;border:1px solid #adc1e9;border-radius:5px;font-style:normal}.am-content{min-height:620px;padding:14px 18px}.am-content h2{margin:3px 0 14px;font-size:1.55rem}.toolbar{display:flex;gap:14px;margin-bottom:16px}.toolbar input{flex:1}.am-content input,.am-content select,.am-content textarea{width:100%;padding:8px 11px;border:1px solid #b8c8e2;border-radius:5px;font:inherit}.am-content form label{display:grid;grid-template-columns:110px 1fr;gap:12px;align-items:center;margin:12px 0;font-weight:600}.am-content textarea{height:160px;resize:vertical}.attachment{display:flex!important;min-height:54px;padding:9px 15px;border:1px dashed #99afe0;border-radius:6px}.attachment input{display:none}.attachment small{font-weight:400;display:block}.message-info{display:grid;grid-template-columns:repeat(4,1fr);padding:11px;background:#f4f7fd;border:1px solid #c5d3e9;border-radius:6px}.message-info span{padding-left:14px;border-left:1px solid #c5d3e9}.message-info b{display:block;margin-top:5px;font-weight:400}.am-content footer{display:flex;gap:14px;justify-content:flex-end;margin-top:16px}.outline,.primary{padding:8px 18px;border:1px solid #0755ed;border-radius:5px;background:#fff;color:#0742d5;font:inherit;cursor:pointer}.danger{color:#bd1111;border-color:#bd1111}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;text-align:center;font-size:calc(1rem - 1px)}th,td{padding:10px 8px;border:1px solid #d9e2f0;font-weight:400}th{background:#f1f6ff;color:#061a8f}.read-meta{display:grid;grid-template-columns:190px 1fr;gap:8px;padding:14px;background:#f8fafc;border:1px solid #ced8e7;border-radius:6px}.read-meta span{text-transform:capitalize}article{white-space:pre-wrap;min-height:180px;margin-top:10px;padding:16px;border:1px solid #ced8e7;border-radius:6px;color:#111}.back{margin-bottom:10px}@media(max-width:800px){.am-shell{grid-template-columns:1fr}.am-shell aside{display:flex;gap:7px}.am-shell aside button{width:auto;flex:1;font-size:.85rem}.message-info{grid-template-columns:1fr 1fr}.am-content{padding:12px}.am-page header{display:block}.am-page header b{display:block;margin:8px}.am-content form label{grid-template-columns:1fr}.read-meta{grid-template-columns:130px 1fr}}</style>
